    public sealed class EditorDialog:Form {
        public readonly FlowLayoutPanel Body=new FlowLayoutPanel();public readonly Button Confirm=new Button{Text=I18n.T("确定"),DialogResult=DialogResult.None,AutoSize=true,MinimumSize=new Size(90,27)};public readonly Button Cancel=new Button{Text=I18n.T("取消"),DialogResult=DialogResult.Cancel,AutoSize=true,MinimumSize=new Size(90,27)};
        public EditorDialog(string title,int height=440){Text=title;ClientSize=new Size(590,height);MinimumSize=new Size(470,300);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",9);ShowInTaskbar=false;Body.Dock=DockStyle.Fill;Body.FlowDirection=FlowDirection.TopDown;Body.WrapContents=false;Body.AutoScroll=true;Body.Padding=new Padding(18,12,18,12);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(8)};footer.Controls.Add(Cancel);footer.Controls.Add(Confirm);Controls.Add(Body);Controls.Add(footer);AcceptButton=Confirm;CancelButton=Cancel;Shown+=(s,e)=>{var owner=Owner as DesktopWindow;if(owner!=null)owner.StyleDialog(this);};}
