        public TextBox TextField(string label,string value,string name="",bool password=false){var input=new TextBox{Text=value??"",Width=525,Name=name,UseSystemPasswordChar=password};Field(label,input);return input;}
        public void Field(string label,Control input){Body.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(0,5,0,4)});input.Margin=new Padding(0,0,0,7);Body.Controls.Add(input);}
        public ComboBox Choice(string label,string[] choices,int selected=0,string name=""){var box=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=525,Name=name};box.Items.AddRange(choices.Select(I18n.T).ToArray());box.SelectedIndex=Math.Max(0,Math.Min(choices.Length-1,selected));Field(label,box);return box;}
        public NumericUpDown Number(string label,int value,int min,int max,string name=""){var number=new NumericUpDown{Minimum=min,Maximum=max,Value=Math.Max(min,Math.Min(max,value)),Width=150,Name=name};Field(label,number);return number;}
        public CheckBox Check(string label,bool value,string name=""){var check=new CheckBox{Text=label,Checked=value,AutoSize=true,Name=name,Margin=new Padding(0,7,0,7)};Body.Controls.Add(check);return check;}
        public TextBox FileField(string label,string value,bool folder=false,bool save=false,string name=""){
            var panel=new Panel{Width=525,Height=29};var input=new TextBox{Text=value??"",Dock=DockStyle.Fill,Name=name};var button=new Button{Text=I18n.T("浏览…"),Dock=DockStyle.Right,Width=80};panel.Controls.Add(input);panel.Controls.Add(button);Field(label,panel);
            button.Click+=(s,e)=>{if(folder){using(var d=new FolderBrowserDialog{SelectedPath=Directory.Exists(input.Text)?input.Text:"",ShowNewFolderButton=true})if(d.ShowDialog(this)==DialogResult.OK)input.Text=d.SelectedPath;}
                else if(save){using(var d=new SaveFileDialog{FileName=input.Text,Filter=I18n.T("所有文件|*.*"),OverwritePrompt=true})if(d.ShowDialog(this)==DialogResult.OK)input.Text=d.FileName;}
                else using(var d=new OpenFileDialog{FileName=input.Text,Filter=I18n.T("所有文件|*.*")})if(d.ShowDialog(this)==DialogResult.OK)input.Text=d.FileName;};return input;
        }
    }
    public sealed partial class DesktopWindow {
        internal string Prompt(string title,string label,string value,bool secret=false){using(var dialog=new EditorDialog(title,180)){var input=dialog.TextField(label,value,"prompt-value",secret);dialog.Confirm.Click+=(s,e)=>dialog.DialogResult=DialogResult.OK;dialog.Shown+=(s,e)=>{input.Focus();input.SelectAll();};return dialog.ShowDialog(this)==DialogResult.OK?input.Text:null;}}
        void ShowText(string title,string text,string name,bool secret=false){var dialog=new Form{Text=title,Name=name,ClientSize=new Size(650,460),StartPosition=FormStartPosition.CenterParent,Font=Font,ShowInTaskbar=false};var content=new TextBox{Text=text,Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Name="text-content"};dialog.Controls.Add(content);if(secret){content.Multiline=false;content.UseSystemPasswordChar=true;content.Dock=DockStyle.Top;var reveal=new CheckBox{Text=I18n.T("显示密码（关闭窗口后清除）"),Dock=DockStyle.Bottom};reveal.CheckedChanged+=(s,e)=>content.UseSystemPasswordChar=!reveal.Checked;dialog.Controls.Add(reveal);dialog.FormClosed+=(s,e)=>content.Clear();}StyleDialog(dialog);dialog.Show(this);}
