        void CreateArchive(string[] initial){using(var dialog=new EditorDialog(I18n.T("新建压缩文件"),650)){
            var sources=new ListBox{Width=525,Height=115,SelectionMode=SelectionMode.MultiExtended,Name="create-sources"};sources.Items.AddRange(initial);dialog.Field(I18n.T("压缩来源"),sources);var actions=new FlowLayoutPanel{Width=525,Height=34};var add=new Button{Text=I18n.T("添加文件…"),Width=110};var folderButton=new Button{Text=I18n.T("添加文件夹…"),Width=120};var remove=new Button{Text=I18n.T("移除所选"),Width=110};actions.Controls.AddRange(new Control[]{add,folderButton,remove});dialog.Body.Controls.Add(actions);
            add.Click+=(s,e)=>{using(var d=new OpenFileDialog{Multiselect=true})if(d.ShowDialog(dialog)==DialogResult.OK)foreach(var p in d.FileNames)if(!sources.Items.Contains(p))sources.Items.Add(p);};folderButton.Click+=(s,e)=>{using(var d=new FolderBrowserDialog())if(d.ShowDialog(dialog)==DialogResult.OK&&!sources.Items.Contains(d.SelectedPath))sources.Items.Add(d.SelectedPath);};remove.Click+=(s,e)=>{foreach(var p in sources.SelectedItems.Cast<string>().ToArray())sources.Items.Remove(p);};
            string first=initial.FirstOrDefault(),defaultPath=first==null?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),I18n.T("新建压缩文件.")+preferences.Str("defaultFormat")):Path.Combine(Path.GetDirectoryName(first),Path.GetFileNameWithoutExtension(first)+"."+preferences.Str("defaultFormat"));
            var formats=ArchiveFormats.CreateFormats;var destination=dialog.FileField(I18n.T("保存为"),defaultPath,false,true,"create-destination");var format=dialog.Choice(I18n.T("格式"),formats.Select(f=>f.ToUpperInvariant()).ToArray(),Array.IndexOf(formats,preferences.Str("defaultFormat")),"create-format");var levels=new[]{0,1,3,5,7,9};var level=dialog.Choice(I18n.T("压缩级别"),new[]{I18n.T("存储 (0)"),I18n.T("最快 (1)"),I18n.T("快速 (3)"),I18n.T("标准 (5)"),I18n.T("较高 (7)"),I18n.T("极限 (9)")},Array.IndexOf(levels,preferences.Int("defaultLevel")),"create-level");var secret=dialog.TextField(I18n.T("密码（可选；中文密码请选择 7Z）"),"","create-password",true);var headers=dialog.Check(I18n.T("7Z 加密文件名"),preferences.Bool("encryptHeaders"));headers.Name="create-headers";var volume=dialog.TextField(I18n.T("分卷大小（ZIP / 7Z，可选，例如 100m）"),"","create-volume");var note=new Label{AutoSize=true,MaximumSize=new Size(525,0),Name="create-format-note"};dialog.Body.Controls.Add(note);
            Action options=()=>{string selected=formats[format.SelectedIndex];secret.Enabled=ArchiveFormats.Password(selected);if(!secret.Enabled)secret.Clear();headers.Enabled=selected=="7z";volume.Enabled=ArchiveFormats.Volumes(selected);if(!volume.Enabled)volume.Clear();level.Enabled=selected!="tar";note.Text=ArchiveFormats.SingleFile(selected)?I18n.T("仅压缩单个文件。多个文件或文件夹请选择 TAR.GZ / TAR.BZ2 / TAR.XZ。"):selected.StartsWith("tar.")?I18n.T("先打包为 TAR 再压缩，保留目录结构；可直接浏览和一步解压。"):selected=="tar"?I18n.T("TAR 仅打包，不压缩，不支持密码。"):selected=="wim"?I18n.T("WIM 适合目录与文件镜像；不支持密码和分卷。"):I18n.T("ZIP / 7Z 支持密码加密和分卷。");};format.SelectedIndexChanged+=(s,e)=>{destination.Text=ArchiveFormats.ChangeFormat(destination.Text,formats[format.SelectedIndex]);options();};options();
            AddVaultPicker(dialog,secret);dialog.Confirm.Text=I18n.T("开始压缩");dialog.Confirm.Click+=(s,e)=>{try{if(sources.Items.Count==0)throw new ArchiveError(I18n.T("请先添加文件或文件夹"));string selected=formats[format.SelectedIndex];if(ArchiveFormats.SingleFile(selected)&&(sources.Items.Count!=1||!File.Exists((string)sources.Items[0])))throw new ArchiveError(I18n.T("此格式仅支持单个文件，请选择 TAR 复合格式压缩多个文件或文件夹"));var p=Json.Obj("sources",sources.Items.Cast<string>().ToArray(),"destination",destination.Text,"format",selected,"level",levels[level.SelectedIndex],"password",secret.Text,"encryptHeaders",headers.Checked,"volume",volume.Text.Trim());StartJob("create",p);secret.Clear();dialog.DialogResult=DialogResult.OK;}catch(Exception error){MessageBox.Show(dialog,error.Message,"NZIP");}};dialog.ShowDialog(this);
        }}
        void ExtractDialog(string[] selected){using(var dialog=new EditorDialog(I18n.T("解压文件"),430)){
            var destination=dialog.FileField(I18n.T("输出目录"),UniqueDirectory(Json.Str(archive,"path")),true,false,"extract-destination");var secret=dialog.TextField(I18n.T("密码（如果需要）"),password,"extract-password",true);var policies=new[]{"overwrite","skip","rename","newer","reject"};var policy=dialog.Choice(I18n.T("遇到同名文件"),new[]{I18n.T("覆盖文件（失败时回滚）"),I18n.T("跳过已有文件"),I18n.T("自动重命名解压文件"),I18n.T("仅覆盖较旧文件"),I18n.T("拒绝已有目录")},0,"extract-existing");dialog.Note(selected.Length>0?I18n.T("仅解压所选项目，保留包内目录结构。可合并到已有目录。"):I18n.T("解压到目标目录，保留已有的其他文件。按上方选项处理同名文件。"));AddVaultPicker(dialog,secret);var p=Payload();dialog.Confirm.Text=I18n.T("开始解压");dialog.Confirm.Click+=(s,e)=>{p["destination"]=destination.Text;p["password"]=secret.Text;p["selected"]=selected;p["existing"]=policies[policy.SelectedIndex];StartJob("extract",p);secret.Clear();dialog.DialogResult=DialogResult.OK;};dialog.ShowDialog(this);
        }}
        static string UniqueDirectory(string archive){string root=Path.GetDirectoryName(archive),name=ArchiveFormats.Stem(archive);string result=Path.Combine(root,name);int i=2;while(File.Exists(result)||Directory.Exists(result))result=Path.Combine(root,name+" ("+(i++)+")");return result;}
        void AddDialog(){using(var dialog=new EditorDialog(I18n.T("添加到压缩包"),260)){dialog.Note(I18n.T("添加到当前包内目录：")+(folder==""?I18n.T("根目录"):folder));var filesButton=new Button{Text=I18n.T("选择文件…"),Width=150};var folderButton=new Button{Text=I18n.T("选择文件夹…"),Width=150};dialog.Body.Controls.Add(filesButton);dialog.Body.Controls.Add(folderButton);dialog.Confirm.Visible=false;filesButton.Click+=(s,e)=>{using(var d=new OpenFileDialog{Multiselect=true})if(d.ShowDialog(dialog)==DialogResult.OK){AddSources(d.FileNames);dialog.DialogResult=DialogResult.OK;}};folderButton.Click+=(s,e)=>{using(var d=new FolderBrowserDialog())if(d.ShowDialog(dialog)==DialogResult.OK){AddSources(new[]{d.SelectedPath});dialog.DialogResult=DialogResult.OK;}};dialog.ShowDialog(this);}}
        internal void AddSources(string[] paths){var p=Payload();p["action"]="add";p["sources"]=paths;p["folder"]=folder;StartJob("modify",p);}
        void Rename(){var selected=Selected().Single();string name=Prompt(I18n.T("重命名文件"),Json.Str(selected,"name"),Json.Str(selected,"name"));if(name==null)return;var p=Payload();p["action"]="rename";p["oldName"]=Json.Str(selected,"path").TrimEnd('/');p["newName"]=name;StartJob("modify",p);}
        void DeleteEntries(){if(preferences.Bool("confirmDelete")&&MessageBox.Show(this,I18n.T("从压缩包删除选中的 ")+Selected().Length+I18n.T(" 项？此操作不能移入回收站。"),"NZIP",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;var p=Payload();p["action"]="delete";p["selected"]=SelectedPaths();StartJob("modify",p);}
        void CommentDialog(){using(var dialog=new EditorDialog(I18n.T("压缩文件注释"),450)){dialog.Note(I18n.T("编辑 ZIP 整包注释，保存为 UTF-8；原包经过验证后更新。其他软件可能按本地代码页显示中文注释。"));var comment=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,Width=525,Height=250,Text=ArchiveTools.Comment(Json.Str(archive,"path"),codePage),Name="archive-comment"};dialog.Body.Controls.Add(comment);dialog.Confirm.Click+=(s,e)=>{var p=Payload();p["comment"]=comment.Text;StartJob("comment",p);dialog.DialogResult=DialogResult.OK;};dialog.ShowDialog(this);}}
        async Task SaveAs(){using(var dialog=new SaveFileDialog{Title=I18n.T("另存为"),FileName=Json.Str(archive,"name"),Filter=I18n.T("压缩文件|*")+Path.GetExtension(Json.Str(archive,"path"))+I18n.T("|所有文件|*.*"),OverwritePrompt=true})if(dialog.ShowDialog(this)==DialogResult.OK){string original=Json.Str(archive,"path"),target=Path.GetFullPath(dialog.FileName);if(target.Equals(original,StringComparison.OrdinalIgnoreCase))throw new ArchiveError(I18n.T("另存为请选择其他文件名"));UseWaitCursor=true;try{await Task.Run(()=>{using(var temp=new TempFolder(Path.GetDirectoryName(target),".nzip-save-")){string file=Path.Combine(temp.Path,"copy");File.Copy(original,file,false);if(File.Exists(target))File.Replace(file,target,null);else File.Move(file,target);}});await OpenArchive(target,password,codePage);}finally{UseWaitCursor=false;}}}
        [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct ShellFileOperation{public IntPtr hwnd;public uint operation;[MarshalAs(UnmanagedType.LPWStr)]public string from;[MarshalAs(UnmanagedType.LPWStr)]public string to;public ushort flags;[MarshalAs(UnmanagedType.Bool)]public bool aborted;public IntPtr mappings;[MarshalAs(UnmanagedType.LPWStr)]public string title;}
        [DllImport("shell32.dll",CharSet=CharSet.Unicode)]static extern int SHFileOperation(ref ShellFileOperation operation);
        void DeleteArchive(bool permanent){string path=Json.Str(archive,"path");bool recycle=!permanent&&preferences.Bool("recycle");if((permanent||preferences.Bool("confirmDelete"))&&MessageBox.Show(this,(recycle?I18n.T("将压缩文件移入回收站？"):I18n.T("永久删除压缩文件？无法撤销。"))+"\n"+path,"NZIP",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;ReleaseArchive();if(recycle){var operation=new ShellFileOperation{hwnd=Handle,operation=3,from=path+"\0\0",flags=0x0040|0x0010|0x0400|0x0004};int result=SHFileOperation(ref operation);if(result!=0||operation.aborted)throw new ArchiveError(I18n.T("未能移入回收站（")+result+I18n.T("），原文件保留"));}else File.Delete(path);ShowHome();}
        internal async Task CopyFiles(){var selected=Selected();if(selected.Length==0)return;var temporary=new TempFolder(preferences.TemporaryRoot,"nzip-clipboard-");try{string destination=Path.Combine(temporary.Path,"files");var p=Payload();p["destination"]=destination;p["selected"]=SelectedPaths();await Task.Run(()=>backend.Engine.Extract(p,CancellationToken.None));var collection=new StringCollection();foreach(var item in selected){var path=Path.GetFullPath(Path.Combine(destination,Json.Str(item,"path").Replace('/',Path.DirectorySeparatorChar)));if(!Json.Within(destination,path))throw new ArchiveError(I18n.T("剪贴板路径无效"));if(!selected.Any(other=>other!=item&&Json.Bool(other,"isDirectory")&&Json.Str(item,"path").StartsWith(Json.Str(other,"path").TrimEnd('/')+"/",StringComparison.Ordinal)))collection.Add(path);}Clipboard.SetFileDropList(collection);clipboardFolders.Add(temporary);message.Text=I18n.T("已复制文件，可粘贴到资源管理器；退出时清理临时副本");}catch{temporary.Dispose();throw;}}
        Func<System.Diagnostics.ProcessStartInfo,System.Diagnostics.Process> localFileLauncher=info=>System.Diagnostics.Process.Start(info);
        internal static string OpenedFilesRoot(DesktopPreferences prefs){return Path.Combine(prefs.TemporaryRoot,"NZIP-opened");}
        internal async Task OpenEntry(){
            var entry=FirstSelectedEntry();if(entry==null||archive==null)return;
            if(Json.Bool(entry,"isDirectory")){GoFolder(Json.Bool(entry,"parent")?Json.Str(entry,"path"):Json.Str(entry,"path").TrimEnd('/')+"/");return;}
            string relative=Json.Str(entry,"path"),ext=Path.GetExtension(relative).ToLowerInvariant(),originalArchive=Json.Str(archive,"path"),openPassword=password;int openPage=codePage;
            if(new[]{".exe",".com",".msi",".msp",".scr",".pif",".lnk",".url",".appref-ms",".application",".hta",".cpl",".msc",".scf",".library-ms",".search-ms",".searchconnector-ms",".settingcontent-ms"}.Contains(ext))throw new ArchiveError(I18n.T("程序、安装包和快捷方式请先解压，再自行打开"));
            bool eligible=new[]{".zip",".zipx"}.Contains(Path.GetExtension(originalArchive).ToLowerInvariant())&&Json.Str(archive,"type").Equals("zip",StringComparison.OrdinalIgnoreCase);
            if(Json.Bool(entry,"encrypted")&&openPassword==""){openPassword=Prompt(I18n.T("输入密码"),Path.GetFileName(originalArchive),"",true);if(openPassword==null)return;}
            var temporary=new TempFolder(OpenedFilesRoot(preferences),"open-");bool launched=false;
            try{
                var payload=Payload();payload["password"]=openPassword;string destination=Path.Combine(temporary.Path,"files");payload["destination"]=destination;payload["selected"]=new[]{relative};
                var pending=backend.ExtractForOpen(payload);if(preferences.Bool("modalProgress"))ShowTasks();await pending;
                if(closing||exitPending)throw new OperationCanceledException();
                string path=Path.GetFullPath(Path.Combine(destination,relative.Replace('/',Path.DirectorySeparatorChar)));
                if(!Json.Within(destination,path)||!File.Exists(path))throw new ArchiveError(I18n.T("未找到解压后的文件"));
                // External editors may still enforce MAX_PATH. Keep a deep entry's
                // independent editing copy at the extraction root instead.
                if(path.Length>259){string local=Path.Combine(destination,Path.GetFileName(path));if(!String.Equals(path,local,StringComparison.OrdinalIgnoreCase))File.Move(path,local);path=local;}
                string originalHash=eligible?await Task.Run(()=>ArchiveEdits.Fingerprint(path,CancellationToken.None)):"";
                if(closing||exitPending)throw new OperationCanceledException();
                var launch=new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true,Verb="open"};System.Diagnostics.Process editor;
                try{editor=localFileLauncher(launch);}catch(System.ComponentModel.Win32Exception error){if(error.NativeErrorCode==1155)throw new ArchiveError(I18n.T("此类型没有关联的本地程序，请在 Windows 中设置默认应用，或先解压后打开"));throw;}
                editSessions.Add(new EditSession{Temporary=temporary,Editor=editor,Archive=originalArchive,Entry=relative,LocalPath=path,OriginalHash=originalHash,Password=openPassword,CodePage=openPage,Eligible=eligible});
                launched=true;message.Text=eligible?(editor==null?I18n.T("已用关联程序打开；该程序未提供退出状态，无法自动检测编辑回写"):I18n.T("已用关联程序打开；保存并关闭编辑器后可选择写回压缩包")):I18n.T("已用关联程序打开；此格式不支持编辑回写");
            }finally{if(!launched)temporary.Dispose();}
        }
        internal async Task Preview(){var entry=FirstSelectedEntry();if(entry==null||archive==null)return;if(Json.Bool(entry,"isDirectory")){GoFolder(Json.Bool(entry,"parent")?Json.Str(entry,"path"):Json.Str(entry,"path").TrimEnd('/')+"/");return;}if(Json.Num(entry,"size")>preferences.Int("previewLimit")*1024L*1024)throw new ArchiveError(I18n.T("文件超过内置内容预览上限，请用本地程序打开"));string ext=Path.GetExtension(Json.Str(entry,"path")).ToLowerInvariant();bool image=new[]{".png",".jpg",".jpeg",".gif",".bmp",".ico",".tif",".tiff"}.Contains(ext);if(!image&&!new[]{".txt",".md",".json",".csv",".log",".xml",".yaml",".yml",".ini",".css",".js",".ts",".html",".cfg",".properties",".java",".cs",".sql"}.Contains(ext))throw new ArchiveError(I18n.T("此类型不支持内置内容预览，请用本地程序打开"));
            using(var temporary=new TempFolder(preferences.TemporaryRoot,"nzip-preview-")){var p=Payload();string destination=Path.Combine(temporary.Path,"files");p["destination"]=destination;p["selected"]=new[]{Json.Str(entry,"path")};await Task.Run(()=>backend.Engine.Extract(p,CancellationToken.None));string path=Path.Combine(destination,Json.Str(entry,"path").Replace('/',Path.DirectorySeparatorChar));if(new FileInfo(ArchivePath.Native(path)).Length>preferences.Int("previewLimit")*1024L*1024)throw new ArchiveError(I18n.T("实际文件超过预览大小上限"));if(image){using(var imageStream=File.OpenRead(path))using(var source=Image.FromStream(imageStream)){if((long)source.Width*source.Height>40L*1000*1000)throw new ArchiveError(I18n.T("图片像素过多，无法预览"));var bitmap=new Bitmap(source);var dialog=new Form{Text=Json.Str(entry,"name")+I18n.T(" - 图片预览"),Name="image-preview",ClientSize=new Size(700,500),StartPosition=FormStartPosition.CenterParent};var picture=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,Image=bitmap,BackColor=Color.FromArgb(240,240,240)};dialog.Controls.Add(picture);dialog.FormClosed+=(s,e)=>bitmap.Dispose();dialog.Show(this);}}else{string text;using(var reader=new StreamReader(File.OpenRead(path),Encoding.GetEncoding(preferences.Int("textEncoding")),true)){var buffer=new char[200001];int count=await reader.ReadBlockAsync(buffer,0,buffer.Length);text=new string(buffer,0,Math.Min(count,200000))+(count>200000?I18n.T("\r\n[已截断至 200,000 个字符]"):"");}ShowText(Json.Str(entry,"name")+I18n.T(" - 文本预览"),text,"text-preview");}}
        }
        void BatchDialog(){using(var d=new OpenFileDialog{Title=I18n.T("选择多个压缩包"),Multiselect=true,Filter=ArchiveFormats.OpenFilter})if(d.ShowDialog(this)==DialogResult.OK){string secret=Prompt(I18n.T("批量解压"),I18n.T("统一密码（无密码留空）"),"",true);if(secret==null)return;foreach(string file in d.FileNames)backend.Dispatch("extract-folder",new object[]{file,secret,codePage});ShowTasks();}}
        void RepairDialog(){using(var dialog=new EditorDialog(I18n.T("修复压缩包"),410)){dialog.Note(I18n.T("从 ZIP 本地文件头恢复可通过 CRC 校验的完整条目，重建新 ZIP；原包保持不变。支持 2 GB 以内 Store / Deflate 普通 ZIP。加密、ZIP64、分卷及已损坏文件内容不支持恢复。"));var source=dialog.FileField(I18n.T("损坏的 ZIP"),archive==null?"":Json.Str(archive,"path"),false,false,"repair-source");var destination=dialog.FileField(I18n.T("另存为新 ZIP"),archive==null?"":Path.Combine(Path.GetDirectoryName(Json.Str(archive,"path")),Path.GetFileNameWithoutExtension(Json.Str(archive,"path"))+"-repaired.zip"),false,true,"repair-output");dialog.Confirm.Text=I18n.T("开始修复");dialog.Confirm.Click+=(s,e)=>{StartJob("repair",Json.Obj("archive",source.Text,"destination",destination.Text,"codePage",codePage));dialog.DialogResult=DialogResult.OK;};dialog.ShowDialog(this);}}
        void RecoverDialog(){using(var dialog=new EditorDialog(I18n.T("密码恢复"),560)){dialog.Note(I18n.T("仅用于你拥有或获准访问的 ZIP / 7Z。使用本地字典或指定字符集枚举，不上传文件或密码。最多 1,000,000 次 / 30 分钟，可在任务窗口取消；不保证成功。"));var source=dialog.FileField(I18n.T("压缩文件"),archive==null?"":Json.Str(archive,"path"),false,false,"recover-source");var dictionary=dialog.FileField(I18n.T("UTF-8 字典文件（每行一个密码，可选，最多 10 MB）"),"",false,false,"recover-dictionary");var chars=dialog.TextField(I18n.T("未选择字典时使用的字符集"),"0123456789","recover-characters");var min=dialog.Number(I18n.T("最短长度"),1,1,12);var max=dialog.Number(I18n.T("最长长度"),4,1,12);dialog.Confirm.Text=I18n.T("开始恢复");dialog.Confirm.Click+=(s,e)=>{StartJob("recover",Json.Obj("archive",source.Text,"dictionary",dictionary.Text,"characters",chars.Text,"minLength",(int)min.Value,"maxLength",(int)max.Value));dialog.DialogResult=DialogResult.OK;};dialog.ShowDialog(this);}}
    }
    sealed class TaskWindow:Form {
        readonly Backend backend;readonly ListView list=new ListView();
        readonly Button reveal=new Button{Text=I18n.T("打开结果位置"),Name="task-open-result",Width=120,Enabled=false};
        readonly Button cancel=new Button{Text=I18n.T("取消所选任务"),Name="task-cancel",Width=120,Enabled=false};
        readonly Label hint=new Label{Text=I18n.T("暂无任务"),Name="task-hint",Dock=DockStyle.Bottom,Height=24,Padding=new Padding(8,3,0,0),AutoEllipsis=true};
        bool updating;
        J SelectedJob{get{return list.SelectedItems.Count==0?null:list.SelectedItems[0].Tag as J;}}
        public TaskWindow(Backend backend){
            this.backend=backend;Text=I18n.T("NZIP 任务");Name="tasks";ClientSize=new Size(750,350);MinimumSize=new Size(550,260);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",9);
            list.Name="task-list";list.Dock=DockStyle.Fill;list.View=View.Details;list.FullRowSelect=true;list.MultiSelect=false;list.HideSelection=false;
            list.Columns.Add(I18n.T("文件"),200);list.Columns.Add(I18n.T("操作"),85);list.Columns.Add(I18n.T("状态"),90);list.Columns.Add(I18n.T("进度"),65);list.Columns.Add(I18n.T("结果"),550);Controls.Add(list);
            var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=40,FlowDirection=FlowDirection.RightToLeft};var close=new Button{Text=I18n.T("关闭"),Width=90};close.Click+=(s,e)=>Close();
            cancel.Click+=(s,e)=>{var job=SelectedJob;if(job!=null)backend.Dispatch("cancel-job",new object[]{Json.Str(job,"id")});};
            reveal.Click+=(s,e)=>{var job=SelectedJob;if(!Backend.HasOpenableResult(job)){UpdateActions();return;}try{backend.Dispatch("open-result",new object[]{Json.Str(job,"id")});hint.Text=I18n.T("已打开所选任务的结果位置");}catch(Exception error){hint.Text=error.Message;if(Environment.GetEnvironmentVariable("NZIP_TEST_MODE")!="1")MessageBox.Show(this,error.Message,"NZIP",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};
            list.SelectedIndexChanged+=(s,e)=>{if(!updating)UpdateActions();};
            bottom.Controls.AddRange(new Control[]{close,cancel,reveal});Controls.Add(hint);Controls.Add(bottom);
        }
        void UpdateActions(){
            var job=SelectedJob;reveal.Enabled=Backend.HasOpenableResult(job);cancel.Enabled=job!=null&&new[]{"queued","running"}.Contains(Json.Str(job,"status"));
            hint.Text=job==null?(list.Items.Count==0?I18n.T("暂无任务"):I18n.T("请选择一项任务")):reveal.Enabled?Json.Str(Json.Map(Json.Get(job,"result")),"path"):new[]{"queued","running","cancelling"}.Contains(Json.Str(job,"status"))?I18n.T("任务尚未完成，完成后可打开输出位置"):I18n.T("所选任务没有可打开的输出位置");
        }
        public void UpdateJobs(J[] current){
            string selected=SelectedJob==null?"":Json.Str(SelectedJob,"id");
            var types=new Dictionary<string,string>{{"create",I18n.T("压缩")},{"extract",I18n.T("解压")},{"test",I18n.T("测试")},{"modify",I18n.T("修改")},{"scan",I18n.T("扫描")},{"repair",I18n.T("修复")},{"recover",I18n.T("恢复密码")},{"comment",I18n.T("注释")},{"writeback",I18n.T("编辑回写")},{"sfx",I18n.T("自解压")}};
            var states=new Dictionary<string,string>{{"queued",I18n.T("排队")},{"running",I18n.T("处理中")},{"cancelling",I18n.T("取消中")},{"completed",I18n.T("完成")},{"failed",I18n.T("失败")},{"cancelled",I18n.T("已取消")}};
            bool rebuild=list.Items.Count!=current.Length||current.Where((job,i)=>Json.Str(job,"id")!=Json.Str(list.Items[i].Tag as J,"id")).Any();
            updating=true;list.BeginUpdate();try{
                if(rebuild)list.Items.Clear();
                for(int i=0;i<current.Length;i++){
                    var job=current[i];string type=Json.Str(job,"type"),state=Json.Str(job,"status");
                    var values=new[]{Json.Str(job,"label"),types.ContainsKey(type)?types[type]:type,states.ContainsKey(state)?states[state]:state,Json.Num(job,"percent")+"%",Json.Str(job,"error",Json.Str(Json.Map(Json.Get(job,"result")),"message"))};
                    ListViewItem item;if(rebuild){item=new ListViewItem(values);list.Items.Add(item);}else{item=list.Items[i];for(int column=0;column<values.Length;column++)if(item.SubItems[column].Text!=values[column])item.SubItems[column].Text=values[column];}item.Tag=job;
                }
                if(list.SelectedItems.Count==0&&current.Length>0){int index=Array.FindIndex(current,j=>Json.Str(j,"id")==selected);if(index<0)index=Array.FindIndex(current,Backend.HasOpenableResult);if(index<0)index=0;list.Items[index].Selected=true;list.Items[index].Focused=true;}
            }finally{list.EndUpdate();updating=false;}UpdateActions();
        }
    }
}
